package com.xdownload.mobile;import org.junit.Test;import static org.junit.Assert.*;public class BrowserPolicyTest{@Test public void hostRulesAreBounded(){assertTrue(BrowserPolicy.block("sub.doubleclick.net",false));assertTrue(BrowserPolicy.block("DOUBLECLICK.NET.",false));assertFalse(BrowserPolicy.block("notdoubleclick.net",false));assertFalse(BrowserPolicy.block("doubleclick.net.example.org",false));assertFalse(BrowserPolicy.block("doubleclick.net",true));assertFalse(BrowserPolicy.block(null,false));}}